mapper.select:


    p.del_flag = '0'
    and p.merchant_id = #{merchantId}

        and (p.product_name like concat('%', #{productName}, '%')
             or p.subtitle like concat('%', #{productName}, '%')
             or p.brand_name like concat('%', #{productName}, '%')
             or m.company_name like concat('%', #{productName}, '%'))

    and p.category_id = #{categoryId}
    and p.status = #{status}

        and exists (
            select 1 from shop_trial_campaign active_trial
            where active_trial.product_id = p.product_id and active_trial.status = 'RECRUITING'
        )


order by p.product_id desc

select image_id, product_id, image_type, image_url, image_sort
from shop_product_image where product_id = #{productId}
order by image_type, image_sort, image_id
